<?php /** @var \Sysfera\Plugin $sf @var array $emps @var string $st @var string $q @var array $roles @var array $teams @var array $users */
include __DIR__ . '/_nav.php'; ?>
<div class="page-h"><h1><?= e($sf->t('nav_employees')) ?></h1></div>
<form method="get" class="row hr-noprint"><select name="status"><?php foreach (['active' => 'es_active', 'dismissed' => 'es_dismissed', '' => 'all'] as $k => $l): ?><option value="<?= e($k) ?>" <?= $st === (string)$k ? 'selected' : '' ?>><?= e($sf->t($l)) ?></option><?php endforeach; ?></select><input name="q" value="<?= e($q) ?>" placeholder="<?= e($sf->t('search')) ?>"><button class="btn"><?= e($sf->t('search')) ?></button></form>
<div class="card flush"><table class="tbl"><tr><th>№</th><th><?= e($sf->t('f_full_name')) ?></th><th><?= e($sf->t('f_position')) ?></th><th><?= e($sf->t('f_department')) ?></th><th><?= e($sf->t('f_emp_type')) ?></th><th><?= e($sf->t('f_hire_date')) ?></th><th><?= e($sf->t('f_status')) ?></th></tr>
  <?php if (!$emps): ?><tr><td colspan="7" class="muted"><?= e($sf->t('none')) ?></td></tr><?php endif; ?>
  <?php foreach ($emps as $x): ?><tr><td><code><?= e($x['number']) ?></code></td><td><a href="<?= e($sf->url('/employees/' . $x['uuid'])) ?>"><?= e($x['full_name']) ?></a><br><span class="muted"><?= e($x['email']) ?></span></td><td><?= e(array_column($roles, 'name', 'uuid')[$x['position_role_uuid']] ?? '') ?></td><td><?= e($x['department']) ?></td><td><?= e($sf->t('et_' . $x['emp_type'])) ?></td><td><?= e($x['hire_date']) ?></td><td><span class="hr-st <?= $hrst($x['status']) ?>"><?= e($sf->t('es_' . $x['status'])) ?></span></td></tr><?php endforeach; ?></table></div>
<?php if ($c->can('hr.employees.edit')): ?><div class="card"><h3><?= e($sf->t('emp_new')) ?></h3>
  <form method="post" action="<?= e($sf->url('/do/employees.create')) ?>"><?= csrf_field() ?>
    <div class="hr-grid"><label><?= e($sf->t('f_full_name')) ?><input name="full_name" required maxlength="160"></label><label><?= e($sf->t('f_email')) ?><input type="email" name="email" required></label><label><?= e($sf->t('f_hire_date')) ?><input type="date" name="hire_date" required></label>
      <label><?= e($sf->t('f_position')) ?><select name="position_role_uuid"><option value=""></option><?php foreach ($roles as $r): ?><option value="<?= e($r['uuid']) ?>"><?= e($r['name']) ?></option><?php endforeach; ?></select></label>
      <label><?= e($sf->t('f_team')) ?><select name="team_uuid"><option value=""></option><?php foreach ($teams as $t): ?><option value="<?= e($t['uuid']) ?>"><?= e($t['name']) ?></option><?php endforeach; ?></select></label>
      <label><?= e($sf->t('f_emp_type')) ?><select name="emp_type"><?php foreach (\SysferaHr\Fields::EMP_TYPES as $t): ?><option value="<?= e($t) ?>"><?= e($sf->t('et_' . $t)) ?></option><?php endforeach; ?></select></label>
      <label><?= e($sf->t('f_user')) ?><select name="user_id"><option value=""></option><?php foreach ($users as $u): ?><option value="<?= (int)$u['id'] ?>"><?= e($u['name']) ?> — <?= e($u['email']) ?></option><?php endforeach; ?></select></label></div>
    <button class="btn primary"><?= e($sf->t('add')) ?></button></form></div><?php endif; ?>
